1: (() => {
2:   'use strict';
3: 
4:   const STORAGE_KEY = 'drop-count-state-v1';
5:   const BASE_PROBABILITY = 1 / 137500;
6:   const $ = (selector) => document.querySelector(selector);
7:   const list = $('#match-list');
8:   let toastTimer;
9:   let state = loadState();
10:   let editingSetup = false;
11: 
12:   function blankState() {
13:     return { onboarded: false, historicalMatches: 0, averageChests: 20, initialTotal: 0, multiplier: 1, tokenObtained: false, matches: [] };
14:   }
15: 
16:   function loadState() {
17:     try {
18:       const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
19:       if (!saved || typeof saved !== 'object') return blankState();
20:       const initialTotal = Math.max(0, Number(saved.initialTotal) || 0);
21:       return {
22:         onboarded: saved.onboarded === true,
23:         historicalMatches: Math.max(0, Math.floor(Number(saved.historicalMatches) || 0)),
24:         averageChests: Math.max(0, Number(saved.averageChests) || 0),
25:         initialTotal,
26:         multiplier: [1, 1.5, 2].includes(Number(saved.multiplier)) ? Number(saved.multiplier) : 1,
27:         tokenObtained: saved.tokenObtained === true,
28:         matches: Array.isArray(saved.matches) ? saved.matches.map((match, index) => ({
29:           id: String(match.id || `${Date.now()}-${index}`),
30:           name: typeof match.name === 'string' && match.name.trim() ? match.name.trim() : `Match ${index + 1}`,
31:           count: Math.max(0, Math.floor(Number(match.count) || 0))
32:         })) : []
33:       };
34:     } catch (error) {
35:       return blankState();
36:     }
37:   }
38: 
39:   function save() {
40:     try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
41:     catch (error) { showToast('Could not save — browser storage may be full.'); }
42:   }
43: 
44:   function totalChests() {
45:     return state.initialTotal + state.matches.reduce((total, match) => total + match.count, 0);
46:   }
47: 
48:   function formatNumber(number) {
49:     return new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(number);
50:   }
51: 
52:   function probabilityPercent() {
53:     const p = Math.min(BASE_PROBABILITY * state.multiplier, 1);
54:     const n = totalChests();
55:     return (1 - Math.exp(n * Math.log1p(-p))) * 100;
56:   }
57: 
58:   function render() {
59:     $('#main-content').hidden = !state.onboarded;
60:     $('#settings-button').hidden = !state.onboarded;
61:     if (!state.onboarded) {
62:       openSetup(false);
63:       return;
64:     }
65:     $('#total-count').textContent = formatNumber(totalChests());
66:     $('#probability').textContent = probabilityPercent().toFixed(5);
67:     $('#match-summary').textContent = `Across ${state.matches.length} ${state.matches.length === 1 ? 'match' : 'matches'}`;
68:     $('#match-count').textContent = state.matches.length;
69:     document.querySelectorAll('.multiplier').forEach((button) => {
70:       const active = Number(button.dataset.multiplier) === state.multiplier;
71:       button.classList.toggle('active', active);
72:       button.setAttribute('aria-pressed', String(active));
73:       button.setAttribute('aria-label', `${button.dataset.multiplier} times multiplier`);
74:     });
75:     list.replaceChildren(...state.matches.map((match, index) => createMatchRow(match, index)));
76:     $('#empty-state').hidden = state.matches.length > 0;
77:     $('#token-banner').classList.toggle('won', state.tokenObtained);
78:     $('#token-title').textContent = state.tokenObtained ? 'Token secured. GG!' : 'Found the Pirate Shop Token?';
79:     $('#token-copy').textContent = state.tokenObtained ? 'Your win is saved. Your chest log is still here whenever you need it.' : 'Mark your win here. Your chest log stays right where it is.';
80:     $('#got-token').innerHTML = state.tokenObtained ? '<span>✓</span> I got the Token!' : '<span>✦</span> I got the Token!';
81:   }
82: 
83:   function createMatchRow(match, index) {
84:     const row = document.createElement('article');
85:     row.className = 'match-row';
86:     const nameWrap = document.createElement('div');
87:     nameWrap.className = 'match-name-wrap';
88:     const indexLabel = document.createElement('span');
89:     indexLabel.className = 'match-index';
90:     indexLabel.textContent = String(index + 1).padStart(2, '0');
91:     const name = document.createElement('input');
92:     name.className = 'match-name';
93:     name.type = 'text';
94:     name.maxLength = 36;
95:     name.value = match.name;
96:     name.setAttribute('aria-label', `Match ${index + 1} name`);
97:     name.addEventListener('change', () => {
98:       const cleaned = name.value.trim();
99:       if (!cleaned) {
100:         name.value = match.name;
101:         showToast('A match needs a name.');
102:         return;
103:       }
104:       match.name = cleaned;
105:       save();
106:       name.value = cleaned;
107:     });
108:     name.addEventListener('keydown', (event) => {
109:       if (event.key === 'Enter') name.blur();
110:     });
111:     nameWrap.append(indexLabel, name);
112: 
113:     const count = document.createElement('div');
114:     count.className = 'match-count';
115:     count.append(document.createTextNode(formatNumber(match.count)));
116:     const countLabel = document.createElement('small');
117:     countLabel.textContent = match.count === 1 ? 'CHEST' : 'CHESTS';
118:     count.append(countLabel);
119: 
120:     const actions = document.createElement('div');
121:     actions.className = 'counter-actions';
122:     const subtract = document.createElement('button');
123:     subtract.className = 'counter-button';
124:     subtract.type = 'button';
125:     subtract.textContent = '−';
126:     subtract.disabled = match.count === 0;
127:     subtract.setAttribute('aria-label', `Subtract 2 chests from ${match.name}`);
128:     subtract.title = 'Subtract 2 chests';
129:     subtract.addEventListener('click', () => changeCount(match.id, -2));
130:     const add = document.createElement('button');
131:     add.className = 'counter-button plus';
132:     add.type = 'button';
133:     add.textContent = '+';
134:     add.setAttribute('aria-label', `Add 1 chest to ${match.name}`);
135:     add.title = 'Add 1 chest';
136:     add.addEventListener('click', () => changeCount(match.id, 1));
137:     actions.append(subtract, add);
138: 
139:     const remove = document.createElement('button');
140:     remove.className = 'delete-button';
141:     remove.type = 'button';
142:     remove.setAttribute('aria-label', `Delete ${match.name}`);
143:     remove.title = 'Delete match';
144:     remove.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M5 7l1 14h12l1-14M9 7V4h6v3"/></svg>';
145:     remove.addEventListener('click', () => {
146:       if (!window.confirm(`Delete “${match.name}” and its ${match.count} chests?`)) return;
147:       state.matches = state.matches.filter((item) => item.id !== match.id);
148:       save();
149:       render();
150:       showToast('Match deleted. Your estimate has been updated.');
151:     });
152:     row.append(nameWrap, count, actions, remove);
153:     return row;
154:   }
155: 
156:   function changeCount(id, amount) {
157:     const match = state.matches.find((item) => item.id === id);
158:     if (!match) return;
159:     match.count = Math.max(0, match.count + amount);
160:     save();
161:     render();
162:   }
163: 
164:   function addMatch() {
165:     const next = state.matches.length + 1;
166:     state.matches.push({ id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, name: `Match ${next}`, count: 0 });
167:     save();
168:     render();
169:     const lastInput = list.lastElementChild?.querySelector('.match-name');
170:     lastInput?.focus();
171:     showToast('New match added. Good luck out there.');
172:   }
173: 
174:   function openSetup(editing) {
175:     editingSetup = editing;
176:     const layer = $('#setup-layer');
177:     layer.hidden = false;
178:     $('#close-setup').hidden = !editing;
