const refs = [...html.matchAll(/data-i18n(?:-aria|-title)?="([\w]+)"/g)].map(([, key]) => key);
for (const [lang, keys] of parsed) {
  const missing = [...new Set(refs)].filter(key => !keys.has(key));
  if (missing.length) throw new Error(`${lang} missing markup translations: ${missing.join(', ')}`);
}
const base = parsed[0][1];
for (const [lang, keys] of parsed.slice(1)) {
  const missing = [...base].filter(key => !keys.has(key));
  const extra = [...keys].filter(key => !base.has(key));
  if (missing.length || extra.length) throw new Error(`${lang} dictionary mismatch; missing=${missing}, extra=${extra}`);
}
console.log(`Translation check passed: ${parsed.length} dictionaries, ${base.size} matching keys, ${new Set(refs).size} static references.`);
