node --check app.js && node <<'NODE'
const fs = require('fs');
const js = fs.readFileSync('app.js', 'utf8');
const html = fs.readFileSync('index.html', 'utf8');
const dictionaries = [...js.matchAll(/^    (en|es|fr): \{([\s\S]*?)^    \}/gm)].map(([, lang, body]) => [lang, new Set([...body.matchAll(/^      ([\w]+):/gm)].map(([, key]) => key))]);
const references = [...html.matchAll(/data-i18n(?:-aria|-title)?="([\w]+)"/g)].map(([, key]) => key);
for (const [lang, keys] of dictionaries) {
  const missing = [...new Set(references)].filter(key => !keys.has(key));
  if (missing.length) throw Error(`${lang} missing ${missing.join(', ')}`);
}
const base = dictionaries[0][1];
for (const [lang, keys] of dictionaries.slice(1)) {
  if (keys.size !== base.size || [...base].some(key => !keys.has(key))) throw Error(`${lang} dictionary does not match English`);
}
console.log(`Translations valid: ${dictionaries.length} dictionaries, ${base.size} matching keys, ${new Set(references).size} static references.`);
NODE
